head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/PopupCalendar.js");
//#include("../js/common.js");

scwin.vScrenID = 'ULDSTF80000.xml';
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    var vFORM_CD = $c.stf.getObjectValue(txb_FORM_CD);
    var vFILTER = $c.stf.getObjectValue(txb_FILTER);
    if (vFORM_CD == "") {
        $c.win.alert("서식코드를 입력하세요.");
        txb_FORM_CD.focus();
        return;
    }
    var url = "/DisclosureStatistics.do?method=listOldDsclItems";
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FILTER=" + vFILTER;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.stf.PanelMsg(panel_msg, "로딩중...기다려주세요.");
    $c.stf.PanelMsg(panel_msg2, "로딩중...기다려주세요.");
    dts_ACODE.DataID = encodeURI(url);
    dts_ACODE.Reset();
    url = "/DisclosureStatistics.do?method=listOldDsclSample";
    url += "&FORM_CD=" + vFORM_CD;
    dts_ACPT.DataID = url;
    dts_ACPT.Reset();
};
scwin.fn_Save = function() {
    var res = window.confirm("저장?");
    if (res) {
        var url = "/DisclosureStatistics.do?method=saveOldDsclItems";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_ACODE)";
        trs_Save.Post();
    }
};
scwin.fn_Filter = function() {
    scwin.fn_Search();
};
scwin.fn_SyncAcode = function() {
    for (var i = 1; i <= dts_ACODE.getTotalRow(); i++) {
        var vSORT_ORD = dts_ACODE.getCellData(i, "SORT_ORD");
        if (dts_ACODE.getCellData(i, "SORT_ORD") != "") {
            var vACODE = dts_ACODE.getCellData(i, "ACODE");
            var vELMT_KOR_NM = dts_ACODE.getCellData(i, "ELMT_KOR_NM");
            for (var j = 0; j <= dts_ACODE.getTotalRow(); j++) {
                var vSORT_ORD2 = dts_ACODE.getCellData(j, "SORT_ORD");
                var vACODE2 = dts_ACODE.getCellData(j, "ACODE");
                if (vSORT_ORD2 == "") {
                    if (vACODE == vACODE2) {
                        dts_ACODE.setCellData(j, "SORT_ORD", vSORT_ORD);
                        dts_ACODE.setCellData(j, "ELMT_KOR_NM", vELMT_KOR_NM);
                    }
                    //continue;

                }
            }
        }
    }
};
scwin.fn_SetOrder = function(row, colid) {
    // grd_ACODE
    var sMax = 1;
    if (colid == "NEXT") {
        for (var i = 1; i <= dts_ACODE.getTotalRow(); i++) {
            var sOrder = dts_ACODE.getCellData(i, "SORT_ORD");
            if (sOrder != "") {
                if (sMax > parseInt(sOrder, 10)) {
                    $c.stf.setObjectValue(txb_MAX, sMax + 1);
                } else {
                    sMax = parseInt(sOrder, 10);
                }
            }
        }
        dts_ACODE.setCellData(row, "SORT_ORD", $c.stf.getObjectValue(txb_MAX));
    }
};
scwin.grd_ACODE_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.dts_ACODE_OnLoadCompleted = function(rowcount) {
    $c.stf.PanelMsg(panel_msg, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
};
scwin.dts_ACODE_OnLoadError = function() {
    $c.stf.alert_error(dts_ACODE);
};
scwin.txb_FORM_CD_onkeypress = function() {
    if (event.keyCode == 13) {
        scwin.fn_Search();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    scwin.fn_Search();
};
scwin.grd_ACPT_OnDblClick = function(row, colid) {
    var AcptNo = dts_ACPT.getCellData(row, "ACPT_NO");
    //alert(AcptNo);
    $c.stf.fn_OpenDisclViewer(AcptNo, "R");
};
scwin.dts_ACPT_OnLoadCompleted = function(rowcount) {
    $c.stf.PanelMsg(panel_msg2, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
};
scwin.dts_ACPT_OnLoadError = function() {
    $c.stf.alert_error(dts_ACPT);
};
scwin.btn_FILTER_onclick = function() {
    scwin.fn_Filter();
};
scwin.txb_FILTER_onkeypress = function() {
    if (event.keyCode == 13) {
        scwin.fn_Filter();
    }
};
scwin.btn_SyncAcode_onclick = function() {
    scwin.fn_SyncAcode();
};
scwin.grd_ACODE_OnDblClick = function(row, colid) {
    scwin.fn_SetOrder(row, colid);
};
scwin.btn_RemoveOrder_onclick = function() {
    for (var i = 1; i <= dts_ACODE.getTotalRow(); i++) {
        dts_ACODE.setCellData(i, "SORT_ORD", "");
    }
};
